(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.008-t*0.15)*25+Math.cos((x+y)*0.012+t*0.1)*15;
  const w2y = Math.cos(y*0.009+t*0.18)*25+Math.sin((x-y)*0.011-t*0.12)*15;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.85],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.05],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*50,0.11,2.1,0.9],
    [400+Math.cos(t*0.55+1)*60,200+Math.sin(t*0.75+4)*60,0.13,1.8,1.1]
  ];
  let aS=0,iS=0,eS=0;
  for(const[sX,sY,f,sp,wt]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*wt;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*wt;
    eS+=Math.sin(d*f*1.3-t*sp*0.8+3.0)*wt;
  }
  const n=src.length,act=aS/n,inh=iS/n,exc=eS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.07+sy*0.01-t*0.6)+Math.sin(-sx*0.02+sy*0.06+t*0.9))/4+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.08-ang*2+t*0.9)+Math.sin(dist*0.03+ang*5-t*2.0))*0.25;
  const pulse=Math.sin(dist*0.06-t*3)*Math.exp(-dist*0.003)*0.3;
  const moire=(Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+3)*0.14+0.5)*Math.sin((sy+2)*0.14-0.3))*0.5;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral+pulse)*2.5);
  const rd2=Math.tanh((exc*0.6+act*0.4-inh*0.5+spiral*0.5)*2.0);
  const cell=Math.tanh((moire+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const cross=Math.sin(t*0.4)*0.5+0.5;
  const reaction=rd1*(1-cross*0.3)+rd2*cross*0.3;
  const blend=reaction*0.7+cell*0.3;
  const v=blend*0.5+0.5;
  const pal=[[5,12,52],[12,45,88],[18,90,115],[25,140,130],[80,175,120],[180,185,80],[220,175,55],[210,120,65],[175,65,75],[130,45,90],[80,30,85],[40,20,70],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.7?1.2:(Math.abs(reaction)>0.5?1.08:1.0);
  const aS2=Math.sin(ang*2+t*0.3)*0.04;
  const vig=1.0-Math.pow(dist/280,3)*0.25;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f+aS2*30)*lum*edge*vig))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f-aS2*15)*lum*edge*vig))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f+aS2*20)*lum*edge*vig))|0
  ];
}
